<script setup lang="ts">
import { ArrowUpRight, Check, CreditCard } from 'lucide-vue-next'
definePageMeta({ layout: 'app' })
const api = useApi()
const { data: plans } = await useAsyncData('billing-plans', () => api.request<any[]>('/plans').catch(() => []))
const { data: sub, refresh } = await useAsyncData('billing-sub', () => api.request<any>('/portal/subscription').catch(() => null))
const { data: invoices, refresh: refreshInvoices } = await useAsyncData('billing-invoices', () => api.request<any[]>('/portal/invoices').catch(() => []))
async function payInvoice(id: string) { await api.request(`/portal/invoices/${id}/pay`, { method: 'POST' }); await refreshInvoices() }
const miles = ref(sub.value?.miles || 48); const saving = ref('')
async function choose(slug: string) { saving.value = slug; try { await api.request('/portal/subscription', { method: 'POST', body: { planSlug: slug, miles: miles.value } }); await refresh() } finally { saving.value = '' } }
</script>
<template>
  <div><PortalHeader><template #eyebrow>Commercial</template><template #title>Billing & plan.</template><template #subtitle>Annual integrity subscription, seats and usage across the workspace.</template></PortalHeader>
    <div class="grid gap-5 lg:grid-cols-12"><div class="lg:col-span-8"><div class="grid gap-3 md:grid-cols-3"><div v-for="(p,i) in plans" :key="p.slug" class="flex flex-col rounded-xl border p-5" :class="sub?.planSlug === p.slug ? 'border-mint bg-mint/10' : 'border-ink/12 bg-bone'"><div class="flex items-center justify-between"><p class="font-mono text-[8.5px] uppercase tracking-[.08em] text-ink/75">{{ p.name }}</p><span v-if="sub?.planSlug === p.slug" class="rounded-full bg-mint px-2 py-0.5 font-mono text-[7.5px] uppercase text-ink">Current</span></div><p class="mt-6 font-display text-[32px]">${{ p.pricePerMile }}<span class="text-[10px] font-sans text-ink/75">/mi</span></p><p class="mt-1 text-[10px] text-ink/75">{{ money(p.minMonthly) }}/mo minimum</p><ul class="mt-4 flex-1 space-y-1.5"><li v-for="f in p.features.slice(0,3)" :key="f" class="flex gap-1.5 text-[10.5px] text-ink/75"><Check :size="11" class="mt-0.5 shrink-0 text-mint-deep" />{{ f }}</li></ul><button class="btn mt-4 w-full !min-h-8 !text-[9px]" :class="i===1?'btn-dark':'btn-outline'" :disabled="saving===p.slug" @click="choose(p.slug)">{{ saving===p.slug ? 'Updating…' : 'Choose plan' }}</button></div></div>
      <div class="mt-4 rounded-xl border border-ink/12 bg-bone p-5"><div class="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p class="font-display text-[20px]">Miles under management</p><p class="mt-1 text-[11.5px] text-ink/75">Used to calculate the annual subscription. You can adjust it at renewal.</p></div><div class="flex items-center gap-3"><input v-model.number="miles" type="range" min="1" max="500" class="accent-[#ff5a1f]"><span class="w-16 text-right font-display text-[26px]">{{ miles }}</span></div></div></div>
    </div><aside class="lg:col-span-4"><div class="rounded-xl bg-ink p-5 text-bone"><p class="flex items-center gap-2 font-mono text-[8px] uppercase tracking-[.08em] text-mint"><CreditCard :size="12" /> Current subscription</p><template v-if="sub"><p class="mt-4 font-display text-[27px] capitalize">{{ sub.planSlug }}</p><p class="mt-1 text-[12px] text-bone/75">{{ sub.miles }} miles · {{ money(sub.annualValue) }} / year</p><div class="mt-4 border-t border-bone/10 pt-3"><p class="font-mono text-[8px] uppercase tracking-[.08em] text-bone/75">Renews</p><p class="mt-1 text-[12px]">{{ shortDate(sub.renewsAt) }}</p></div><button class="btn btn-mint mt-5 w-full !min-h-9 !text-[9px]">Manage payment method</button></template><p v-else class="mt-3 text-[12px] text-bone/75">No active plan. Choose a plan to start.</p></div><div class="mt-3 rounded-xl border border-ink/12 p-4"><p class="font-mono text-[8px] uppercase tracking-[.08em] text-ink/75">Need procurement?</p><p class="mt-1 text-[11.5px] leading-relaxed text-ink/75">Annual plans can be invoiced against a PO. Talk to <NuxtLink to="/contact" class="font-semibold text-signal-deep">sales <ArrowUpRight :size="9" class="inline" /></NuxtLink>.</p></div></aside></div>
    <div class="mt-5 overflow-hidden rounded-xl border border-ink/12 bg-bone"><div class="flex items-center justify-between border-b border-ink/10 px-4 py-3"><p class="font-display text-[18px]">Invoices & receipts</p><span class="font-mono text-[9px] uppercase tracking-[.06em] text-ink/75">Payment ledger</span></div><div class="overflow-auto"><table class="w-full text-left text-[11px]"><thead class="bg-paper font-mono text-[7.5px] uppercase tracking-[.08em] text-ink/75"><tr><th class="px-4 py-2.5">Invoice</th><th class="px-4 py-2.5">Type</th><th class="px-4 py-2.5">Total</th><th class="px-4 py-2.5">Status</th><th class="px-4 py-2.5">Issued</th><th class="px-4 py-2.5"></th></tr></thead><tbody><tr v-for="inv in invoices" :key="inv._id" class="border-t border-ink/10"><td class="px-4 py-3 font-mono text-[9px]">{{ inv.ref }}</td><td class="px-4 py-3 capitalize">{{ String(inv.type).replace('_',' ') }}</td><td class="px-4 py-3">{{ money(inv.total) }}</td><td class="px-4 py-3"><StatusPill :status="inv.status"/></td><td class="px-4 py-3 text-ink/75">{{ shortDate(inv.createdAt) }}</td><td class="px-4 py-3"><div class="flex gap-2"><button class="text-[9px] font-semibold text-signal-deep" @click="api.download(`/portal/invoices/${inv._id}/pdf`, `vomtek-${inv.ref}.pdf`)">PDF</button><button v-if="inv.status !== 'paid'" class="text-[9px] font-semibold text-mint-deep" @click="payInvoice(inv._id)">Pay</button></div></td></tr></tbody></table></div><div v-if="!invoices?.length" class="p-6 text-center text-[12px] text-ink/75">No invoices yet.</div></div>
  </div>
</template>
